jobs.script:
#!/bin/bash
# backup with an exclusive lock so double-runs are impossible
flock -n /var/lock/nightly-backup.lock /usr/local/bin/run-backup.sh

#!/bin/bash
# uses INSERT ... ON CONFLICT DO NOTHING, safe to re-run
psql "$DB" -c "INSERT INTO daily_report ... ON CONFLICT (day) DO NOTHING;"

#!/bin/bash
# fire-and-forget ping, no locking at all
curl -s https://example.com/ping
